<?php require_once __DIR__.'/../includes/functions.php';require_role('student');$s=$pdo->prepare("SELECT attendance_date,status FROM attendance a JOIN students s ON s.id=a.student_id WHERE s.user_id=? ORDER BY attendance_date DESC");$s->execute([$_SESSION['user']['id']]);$rows=$s->fetchAll();$pageTitle='My Attendance';$base='../';require __DIR__.'/../includes/header.php';?>
<div class="layout"><?php require __DIR__.'/../includes/sidebar.php';?><section class="content"><div class="card"><h1>My Attendance</h1><div class="table-wrap"><table class="table"><?php if($rows):?><tr><?php foreach(array_keys($rows[0]) as $h):?><th><?=e(ucwords(str_replace('_',' ',$h)))?></th><?php endforeach;?></tr><?php foreach($rows as $r):?><tr><?php foreach($r as $v):?><td><?=e((string)$v)?></td><?php endforeach;?></tr><?php endforeach;?><?php endif;?></table></div></div></section></div><?php require __DIR__.'/../includes/footer.php';?>